### 2️⃣ `shipments.controller.ts` – Basic CRUD Endpoints

```ts
import { Controller, Get, Post, Body, Param, Delete, Put, UseGuards } from '@nestjs/common';
import { JwtAuthGuard } from '../middlewares/auth.guard';
import { CreateShipmentDto } from './dtos/create-shipment.dto';
import { UpdateShipmentDto } from './dtos/update-shipment.dto';
import { ShippingService } from '../services/shipping.service';

@Controller('shipments')
@UseGuards(JwtAuthGuard)
export class ShipmentsController {
  constructor(private readonly shippingSvc: ShippingService) {}

  @Post()
  async create(@Body() dto: CreateShipmentDto) {
    return this.shippingSvc.create(dto);
  }

  @Get(':id')
  async readOne(@Param('id') id: string) {
    return this.shippingSvc.findById(id);
  }

  @Put(':id')
  async update(@Param('id') id: string, @Body() dto: UpdateShipmentDto) {
    return this.shippingSvc.update(id, dto);
  }

  @Delete(':id')
  async delete(@Param('id') id: string) {
    return this.shippingSvc.delete(id);
  }

  @Get('/search')
  async search(@Query() queryParams) {
    return this.shippingSvc.search(queryParams);
  }
}
```

> 👉 All endpoints are protected by JWT middleware. Add `/login` and `/register` routes elsewhere.

---

### 3️⃣ `.env.example` – Environment Variables

```
DATABASE_URL=postgresql://db_user:password@localhost:5432/tms_db
MAPBOX_TOKEN=<YOUR_MAPBOX_ACCESS_TOKEN>
JWT_SECRET=somesecretkey12345
OPEN_METEO_API=https://api.open-meteo.com/v1/forecast
PORT=4000
NODE_ENV=development
```

Copy this file to `.env` and fill in the secrets. Never commit actual credentials!

